#include <GLFW/glfw3.h>

#include <algorithm>
#include <cstdio>
#include <cstring>
#include <string>

#include "AppIcon.h"  // generated by cmake/EmbedIcon.cmake
#include "app/App.h"
#include "app/NativeWindow.h"
#include "app/Theme.h"
#include "imgui.h"
#include "imgui_impl_glfw.h"
#include "imgui_impl_opengl3.h"
#include "platform/AppBus.h"
#include "platform/Appearance.h"
#include "platform/Paths.h"
#include "platform/X11Desktop.h"
#include "stb_image.h"

namespace {

void setWindowIcon(GLFWwindow* window) {
    int w, h, channels;
    unsigned char* pixels = stbi_load_from_memory(kAppIconPng, sizeof kAppIconPng, &w, &h, &channels, 4);
    if (!pixels) return;
    GLFWimage image{w, h, pixels};
    glfwSetWindowIcon(window, 1, &image);  // glfw copies it
    stbi_image_free(pixels);
}

// work area of the monitor the point is on (the first one if none)
void workAreaAt(int px, int py, int* x, int* y, int* w, int* h) {
    int count = 0;
    GLFWmonitor** monitors = glfwGetMonitors(&count);
    *x = *y = 0;
    *w = 1920;
    *h = 1080;
    for (int i = 0; i < count; ++i) {
        int mx, my, mw, mh;
        glfwGetMonitorWorkarea(monitors[i], &mx, &my, &mw, &mh);
        const bool inside = px >= mx && px < mx + mw && py >= my && py < my + mh;
        if (i == 0 || inside) *x = mx, *y = my, *w = mw, *h = mh;
        if (inside) return;
    }
}

// saved spot has to still be on a monitor (screens get unplugged)
void restoreGeometry(GLFWwindow* window, const clipper::WindowGeometry& g) {
    if (g.width >= 400 && g.height >= 300) glfwSetWindowSize(window, g.width, g.height);
    if (g.x < 0 || g.y < 0) return;
    int count = 0;
    GLFWmonitor** monitors = glfwGetMonitors(&count);
    for (int i = 0; i < count; ++i) {
        int mx, my, mw, mh;
        glfwGetMonitorWorkarea(monitors[i], &mx, &my, &mw, &mh);
        if (g.x + 50 >= mx && g.x + 50 < mx + mw && g.y + 50 >= my && g.y + 50 < my + mh) {
            glfwSetWindowPos(window, g.x, g.y);
            return;
        }
    }
}

clipper::WindowGeometry captureGeometry(GLFWwindow* window, clipper::WindowGeometry g) {
    if (!glfwGetWindowAttrib(window, GLFW_VISIBLE) || glfwGetWindowAttrib(window, GLFW_ICONIFIED)) return g;
    g.maximized = glfwGetWindowAttrib(window, GLFW_MAXIMIZED);
    if (!g.maximized) {  // keep the normal size around for when it gets un-maximized
        glfwGetWindowPos(window, &g.x, &g.y);
        glfwGetWindowSize(window, &g.width, &g.height);
    }
    return g;
}

}  // namespace

int main(int argc, char** argv) {
    bool background = false;  // the autostart entry passes --minimized
    clipper::AppBus::Request launch;
    for (int i = 1; i < argc; ++i) {
        if (std::strcmp(argv[i], "--minimized") == 0) {
            background = true;
        } else if (std::strcmp(argv[i], "--popup") == 0) {
            launch.kind = clipper::AppBus::Request::Kind::Popup;
        } else if (std::strcmp(argv[i], "--toggle") == 0) {
            launch.kind = clipper::AppBus::Request::Kind::Toggle;
        } else if (std::strcmp(argv[i], "--help") == 0 || std::strcmp(argv[i], "-h") == 0) {
            std::puts(
                "usage: Clipper [--popup] [--toggle] [--minimized]\n"
                "  --popup      open the history popup at the mouse (what the shortcut runs)\n"
                "  --toggle     show / hide the manager window\n"
                "  --minimized  start in the tray (login autostart)");
            return 0;
        }
    }

    // two threads talk to X (the clipboard thread has its own connection), make xlib thread safe first
    clipper::initXlibThreads();
    glfwSetErrorCallback([](int code, const char* msg) { std::fprintf(stderr, "GLFW error %d: %s\n", code, msg); });
    glfwInitHint(GLFW_PLATFORM, GLFW_PLATFORM_X11);  // the clipboard code is x11 only
    if (!glfwInit()) return 1;

    // already running? pass the request on and quit before opening any window.
    // that's the shortcut path, it has to be quick
    clipper::AppBus bus(launch, [] { glfwPostEmptyEvent(); });
    if (!bus.primary()) {
        glfwTerminate();
        return 0;
    }

    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 0);
    // WM_CLASS, matches StartupWMClass in the .desktop file so the taskbar groups us with the launcher
    glfwWindowHintString(GLFW_X11_CLASS_NAME, "clipper");
    glfwWindowHintString(GLFW_X11_INSTANCE_NAME, "clipper");
    glfwWindowHint(GLFW_VISIBLE, GLFW_FALSE);  // the app decides: manager, popup or just the tray

    GLFWwindow* window = glfwCreateWindow(1000, 640, "Clipper", nullptr, nullptr);
    if (!window) {
        glfwTerminate();
        return 1;
    }
    setWindowIcon(window);
    glfwMakeContextCurrent(window);
    glfwSwapInterval(1);

    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGui::GetIO().IniFilename = nullptr;  // nothing worth keeping, our layout is fixed

    float scaleX = 1.0f, scaleY = 1.0f;  // > 1 on hidpi
    glfwGetWindowContentScale(window, &scaleX, &scaleY);
    clipper::X11Desktop desktop(clipper::x11Display());
    const clipper::X11Desktop::WindowId xid = clipper::x11Window(window);
    {
        clipper::App app(clipper::querySystemAppearance(), scaleX, [] { glfwPostEmptyEvent(); }, desktop);
        app.setOwnWindow(xid);
        clipper::loadFonts(app.appearance(), app.fontScale());

        ImGui_ImplGlfw_InitForOpenGL(window, true);
        ImGui_ImplOpenGL3_Init("#version 130");
        app.start(background);
        if (launch.kind == clipper::AppBus::Request::Kind::Popup) app.remote(launch);  // started by the shortcut

        // X button: hide to the tray instead of quitting, if that's on
        glfwSetWindowUserPointer(window, &app);
        glfwSetWindowCloseCallback(window, [](GLFWwindow* w) {
            auto* a = static_cast<clipper::App*>(glfwGetWindowUserPointer(w));
            if (a->mode() == clipper::App::Mode::Manager)
                a->rememberWindowGeometry(captureGeometry(w, a->windowGeometry()));
            if (!a->hideOnClose()) return;
            glfwSetWindowShouldClose(w, GLFW_FALSE);
            glfwHideWindow(w);
            a->windowChanged(clipper::App::Mode::Hidden);
        });
        // imgui's backend has its own focus callback, chain to it
        static GLFWwindowfocusfun imguiFocus = nullptr;
        imguiFocus = glfwSetWindowFocusCallback(window, [](GLFWwindow* w, int focused) {
            if (imguiFocus) imguiFocus(w, focused);
            static_cast<clipper::App*>(glfwGetWindowUserPointer(w))->focusChanged(focused);
        });

        bool popupLook = false;  // window currently set up as the popup (no frame, no taskbar)
        bool shownOnce = false;
        auto hide = [&] {
            if (app.mode() == clipper::App::Mode::Manager)
                app.rememberWindowGeometry(captureGeometry(window, app.windowGeometry()));
            glfwHideWindow(window);
            app.windowChanged(clipper::App::Mode::Hidden);
        };
        auto bringToFront = [&] {
            glfwFocusWindow(window);
            desktop.activate(xid);  // glfw asks as an app, wms can say no to that
        };
        auto showManager = [&] {
            if (app.mode() == clipper::App::Mode::Popup) hide();
            if (popupLook) {
                glfwSetWindowAttrib(window, GLFW_DECORATED, GLFW_TRUE);
                desktop.setPopupHints(xid, false);
                popupLook = false;
                shownOnce = false;
            }
            if (!shownOnce) restoreGeometry(window, app.windowGeometry());
            glfwShowWindow(window);
            if (glfwGetWindowAttrib(window, GLFW_ICONIFIED)) glfwRestoreWindow(window);
            if (!shownOnce && app.windowGeometry().maximized) glfwMaximizeWindow(window);
            shownOnce = true;
            bringToFront();
            app.windowChanged(clipper::App::Mode::Manager);
        };
        auto showPopup = [&] {
            if (glfwGetWindowAttrib(window, GLFW_VISIBLE)) hide();
            if (!popupLook) {
                glfwSetWindowAttrib(window, GLFW_DECORATED, GLFW_FALSE);
                desktop.setPopupHints(xid, true);
                popupLook = true;
            }
            const float scale = app.fontScale();
            const int w = static_cast<int>(app.settings().popupWidth * scale);
            const int h = static_cast<int>(app.settings().popupHeight * scale);
            int px = 0, py = 0;
            if (!app.popupAnchor(&px, &py)) px = py = 0;
            int ax, ay, aw, ah;
            workAreaAt(px, py, &ax, &ay, &aw, &ah);
            // just below-right of the pointer, pushed back inside the screen
            const int x = std::clamp(px + 8, ax, std::max(ax, ax + aw - w));
            const int y = std::clamp(py + 8, ay, std::max(ay, ay + ah - h));
            glfwSetWindowSize(window, w, h);
            glfwSetWindowPos(window, x, y);
            glfwShowWindow(window);
            bringToFront();
            app.windowChanged(clipper::App::Mode::Popup);
        };

        while (!glfwWindowShouldClose(window)) {
            // sleep until something happens: input, a copy somewhere, a d-bus call. ~0% cpu when idle
            glfwWaitEventsTimeout(glfwGetWindowAttrib(window, GLFW_VISIBLE) ? 0.25 : 1.0);

            for (const clipper::AppBus::Request& request : bus.takeRequests()) app.remote(request);
            app.tick();
            switch (app.takeWindowRequest()) {
                case clipper::App::WindowRequest::Popup:
                    showPopup();
                    break;
                case clipper::App::WindowRequest::Manager:
                    showManager();
                    break;
                case clipper::App::WindowRequest::ToggleManager:
                    if (app.mode() == clipper::App::Mode::Manager && glfwGetWindowAttrib(window, GLFW_FOCUSED) &&
                        !glfwGetWindowAttrib(window, GLFW_ICONIFIED))
                        hide();
                    else
                        showManager();
                    break;
                case clipper::App::WindowRequest::Hide:
                    hide();
                    break;
                case clipper::App::WindowRequest::None:
                    break;
            }
            if (app.quitRequested()) {
                if (app.mode() == clipper::App::Mode::Manager)
                    app.rememberWindowGeometry(captureGeometry(window, app.windowGeometry()));
                break;
            }
            if (!glfwGetWindowAttrib(window, GLFW_VISIBLE)) continue;  // in the tray, nothing to draw

            // imgui 1.91 bakes fonts at a fixed size so zoom = rebuild the atlas between frames
            if (app.consumeFontRebuild()) {
                ImGui::GetIO().Fonts->Clear();
                clipper::loadFonts(app.appearance(), app.fontScale());
                ImGui_ImplOpenGL3_DestroyFontsTexture();
                ImGui_ImplOpenGL3_CreateFontsTexture();
            }

            ImGui_ImplOpenGL3_NewFrame();
            ImGui_ImplGlfw_NewFrame();
            ImGui::NewFrame();
            app.draw();
            ImGui::Render();

            int w, h;
            glfwGetFramebufferSize(window, &w, &h);
            glViewport(0, 0, w, h);
            const ImVec4 bg = ImGui::GetStyle().Colors[ImGuiCol_WindowBg];
            glClearColor(bg.x, bg.y, bg.z, 1.0f);
            glClear(GL_COLOR_BUFFER_BIT);
            ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());
            glfwSwapBuffers(window);
        }
    }  // app (and its gl textures) goes away while the context is still alive

    ImGui_ImplOpenGL3_Shutdown();
    ImGui_ImplGlfw_Shutdown();
    ImGui::DestroyContext();
    glfwDestroyWindow(window);
    glfwTerminate();
    return 0;
}
